#!/bin/sh
# generated by rack:fleet render from infra/rack-switch-fleet/sites/ber2.json
set -e
if ip route show default | awk '{for (i = 1; i < NF; i++) if ($i == "dev") print $(i + 1)}' | grep -qx 'mgmt0'; then
  echo "mgmt0 carries this node's default route; the switches' port is a different one" >&2
  exit 1
fi
if [ "$(cat /proc/sys/net/ipv4/ip_forward)" != 1 ]; then
  echo "net.ipv4.ip_forward is off; the node's converge turns it on" >&2
  exit 1
fi
case "${NODE_NAME:?the pod passes the name of the node it runs on}" in
  ber2-edge-a) vrrp_address=10.255.255.1/29 machines_address=10.20.0.2/24 peer_address=10.255.255.2 uplinks="ens17f0np0 ens17f1np1" ;;
  ber2-edge-b) vrrp_address=10.255.255.2/29 machines_address=10.20.0.3/24 peer_address=10.255.255.1 uplinks="ens17f0np0 ens17f1np1" ;;
  *) echo "$NODE_NAME is not one of the site's edges" >&2; exit 1 ;;
esac
for uplink in $uplinks; do
  ethtool -G "$uplink" rx 4096 tx 4096
done
edge_vlan_bond() {
  bond=$1 vlan=$2 i=0
  ip link show "$bond" >/dev/null 2>&1 || ip link add "$bond" type bond mode active-backup miimon 100
  for uplink in $uplinks; do
    i=$((i + 1))
    member="$bond-$i"
    ip link set "$uplink" up
    ip link show "$member" >/dev/null 2>&1 || ip link add link "$uplink" name "$member" type vlan id "$vlan"
    if [ ! -e "/sys/class/net/$member/master" ]; then
      ip link set "$member" down
      ip link set "$member" master "$bond"
    fi
  done
  ip link set "$bond" up
}
edge_vlan_bond vrrp0 4000
edge_vlan_bond mgmt0 20
ip addr replace "$vrrp_address" dev vrrp0
edge_vlan_bond machines0 10
ip addr replace "$machines_address" dev machines0
edge_vlan_bond wan0 4001
ip route replace default via "$peer_address" dev vrrp0 metric 200 proto static
nexthops=""; for uplink in $uplinks; do nexthops="$nexthops nexthop dev $uplink"; done
ip -o -4 addr show | awk -v port='mgmt0' '$2 != port && ($4 == "192.168.60.10/24" || $4 == "192.168.70.1/24") {print $2, $4}' |
  while read -r dev address; do ip addr del "$address" dev "$dev"; done
nft -f - <<'NFT'
table ip tuist_mgmt_path
delete table ip tuist_mgmt_path
table ip tuist_mgmt_path {
  chain postrouting {
    type nat hook postrouting priority srcnat;
    oifname "tailscale0" ip saddr { 192.168.61.6,192.168.61.2,192.168.70.0/24 } masquerade
    oifname != { "tailscale0", "machines0", "mgmt0" } ip saddr 10.20.0.0/24 masquerade
    oifname "wan0" ip saddr { 10.255.255.0/29, 192.168.60.0/24 } masquerade
  }
  chain forward {
    type filter hook forward priority mangle;
    oifname "tailscale0" ip saddr { 192.168.61.6,192.168.61.2,192.168.70.0/24 } tcp flags & (syn | rst) == syn tcp option maxseg size set rt mtu
  }
}
table netdev tuist_rack_dhcp
delete table netdev tuist_rack_dhcp
table netdev tuist_rack_dhcp {
  chain replies {
    type filter hook egress device "mgmt0" priority 0;
  }
}
table inet tuist_rack_machines
delete table inet tuist_rack_machines
table inet tuist_rack_machines {
  chain forward {
    type filter hook forward priority filter;
    iifname "machines0" ct state established,related accept
    iifname "machines0" oifname { "tailscale0", "vrrp0", "mgmt0" } drop
    iifname "machines0" ip daddr { 192.168.60.0/24, 192.168.70.0/24, 10.255.255.0/29 } drop
  }
  chain input {
    type filter hook input priority filter;
    iifname "machines0" ct state established,related accept
    iifname "machines0" udp dport 67 accept
    iifname "machines0" icmp type echo-request accept
    iifname "machines0" drop
  }
}
table inet tuist_rack_wan
delete table inet tuist_rack_wan
table inet tuist_rack_wan {
  chain input {
    type filter hook input priority filter;
    iifname "wan0" ct state established,related accept
    iifname "wan0" meta l4proto { icmp, ipv6-icmp } accept
    iifname "wan0" udp dport 41641 accept
    iifname "wan0" drop
  }
  chain forward {
    type filter hook forward priority filter;
    iifname "wan0" ct state established,related accept
    iifname "wan0" ct status dnat accept
    iifname "wan0" drop
  }
}
NFT
